'use client';

import React, { useEffect, useState } from 'react';
import { Header } from '../components/layout/header/header';
import { Sidebar } from '../components/layout/sidebar/sidebar';
import { StatsCards } from '../components/inventory/stats-cards/stats-cards';
import { InventoryTable } from '../components/inventory/inventory-table/inventory-table';
import { ItemModal } from '../components/inventory/item-modal/item-modal';
import { InventoryItem } from '../types/inventory';

export default function Home() {
  const [items, setItems] = useState<InventoryItem[]>([]);
  const [isModalOpen, setIsModalOpen] = useState(false);

  // Daten vom Backend abrufen
  const fetchItems = async () => {
    try {
      const res = await fetch('/api/inventory');
      const data = await res.json();
      if (Array.isArray(data)) setItems(data);
    } catch (err) {
      console.error('Fehler beim Laden der Daten', err);
    }
  };

  useEffect(() => {
    fetchItems();
  }, []);

  // Bestand schnell anpassen (+ / -)
  const handleUpdateStock = async (id: string, newStock: number) => {
    try {
      await fetch('/api/inventory', {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ id, stock: newStock }),
      });
      fetchItems();
    } catch (err) {
      console.error('Fehler beim Aktualisieren', err);
    }
  };

  // Artikel löschen
  const handleDeleteItem = async (id: string) => {
    if (!confirm('Möchtest du diesen Artikel wirklich löschen?')) return;
    try {
      await fetch(`/api/inventory?id=${id}`, { method: 'DELETE' });
      fetchItems();
    } catch (err) {
      console.error('Fehler beim Löschen', err);
    }
  };

  // Neuen Artikel speichern
  const handleSaveItem = async (newItem: any) => {
    try {
      await fetch('/api/inventory', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(newItem),
      });
      fetchItems();
    } catch (err) {
      console.error('Fehler beim Speichern', err);
    }
  };

  return (
    <div style={{ minHeight: '100vh', display: 'flex', flexDirection: 'column' }}>
      <Header />
      <div style={{ display: 'flex', flex: 1 }}>
        <Sidebar />
        <main style={{ flex: 1, padding: '1.5rem', backgroundColor: '#f8fafc' }}>
          <StatsCards items={items} />
          <InventoryTable
            items={items}
            onUpdateStock={handleUpdateStock}
            onDeleteItem={handleDeleteItem}
            onOpenAddModal={() => setIsModalOpen(true)}
          />
        </main>
      </div>

      <ItemModal
        isOpen={isModalOpen}
        onClose={() => setIsModalOpen(false)}
        onSave={handleSaveItem}
      />
    </div>
  );
}