'use client';

import React, { useState } from 'react';
import { InventoryItem } from '../../../types/inventory';
import { formatCurrency } from '../../../lib/utils';
import { Badge } from '../../ui/badge';
import { Button } from '../../ui/button';
import { Plus, Minus, Trash2, Download, Search } from 'lucide-react';
import styles from './inventory-table.module.css';

interface InventoryTableProps {
  items: InventoryItem[];
  onUpdateStock: (id: string, newStock: number) => void;
  onDeleteItem: (id: string) => void;
  onOpenAddModal: () => void;
}

export function InventoryTable({
  items,
  onUpdateStock,
  onDeleteItem,
  onOpenAddModal,
}: InventoryTableProps) {
  const [searchTerm, setSearchTerm] = useState('');
  const [selectedCategory, setSelectedCategory] = useState<string>('ALL');

  // Eindeutige Kategorien für Filter-Dropdown extrahieren
  const categories = Array.from(new Set(items.map((item) => item.category)));

  // Filterlogik für Suche und Kategorie
  const filteredItems = items.filter((item) => {
    const matchesSearch =
      item.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
      item.sku.toLowerCase().includes(searchTerm.toLowerCase()) ||
      (item.location && item.location.toLowerCase().includes(searchTerm.toLowerCase()));

    const matchesCategory =
      selectedCategory === 'ALL' || item.category === selectedCategory;

    return matchesSearch && matchesCategory;
  });

  const handleExport = () => {
    window.location.href = '/api/export';
  };

  return (
    <div className={styles.container}>
      {/* Such- & Filterleiste */}
      <div className={styles.controls}>
        <div className={styles.searchGroup}>
          <input
            type="text"
            placeholder="Name, SKU oder Lagerort suchen..."
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
            className={styles.searchInput}
          />

          <select
            value={selectedCategory}
            onChange={(e) => setSelectedCategory(e.target.value)}
            className={styles.selectInput}
          >
            <option value="ALL">Alle Kategorien</option>
            {categories.map((cat) => (
              <option key={cat} value={cat}>
                {cat}
              </option>
            ))}
          </select>
        </div>

        <div className="flex gap-2">
          <Button variant="outline" onClick={handleExport}>
            <Download className="mr-2 h-4 w-4" /> Excel Export
          </Button>
          <Button variant="primary" onClick={onOpenAddModal}>
            <Plus className="mr-2 h-4 w-4" /> Artikel Hinzufügen
          </Button>
        </div>
      </div>

      {/* Die eigentliche Tabelle */}
      <div className={styles.tableWrapper}>
        <table className={styles.table}>
          <thead>
            <tr>
              <th>SKU / Artikel-Nr.</th>
              <th>Name</th>
              <th>Kategorie</th>
              <th>Bestand</th>
              <th>Mindestbestand</th>
              <th>Preis (€)</th>
              <th>Lagerort</th>
              <th>Status</th>
              <th style={{ textAlign: 'right' }}>Aktionen</th>
            </tr>
          </thead>
          <tbody>
            {filteredItems.length === 0 ? (
              <tr>
                <td colSpan={9} className={styles.emptyState}>
                  Keine Artikel gefunden.
                </td>
              </tr>
            ) : (
              filteredItems.map((item) => {
                const isCritical = item.stock <= item.minStock;

                return (
                  <tr key={item.id}>
                    <td style={{ fontWeight: 600 }}>{item.sku}</td>
                    <td>{item.name}</td>
                    <td>{item.category}</td>
                    <td>
                      <div className={styles.stockControl}>
                        <button
                          className={styles.stockBtn}
                          onClick={() => onUpdateStock(item.id, Math.max(0, item.stock - 1))}
                          title="Bestand verringern"
                        >
                          -
                        </button>
                        <span style={{ minWidth: '2rem', textAlign: 'center', fontWeight: 'bold' }}>
                          {item.stock}
                        </span>
                        <button
                          className={styles.stockBtn}
                          onClick={() => onUpdateStock(item.id, item.stock + 1)}
                          title="Bestand erhöhen"
                        >
                          +
                        </button>
                      </div>
                    </td>
                    <td>{item.minStock}</td>
                    <td>{formatCurrency(item.price)}</td>
                    <td>{item.location || '-'}</td>
                    <td>
                      {isCritical ? (
                        <Badge variant="danger">Nachbestellen</Badge>
                      ) : (
                        <Badge variant="success">OK</Badge>
                      )}
                    </td>
                    <td style={{ textAlign: 'right' }}>
                      <button
                        className={styles.actionBtn}
                        onClick={() => onDeleteItem(item.id)}
                        title="Artikel löschen"
                      >
                        <Trash2 className="h-4 w-4" />
                      </button>
                    </td>
                  </tr>
                );
              })
            )}
          </tbody>
        </table>
      </div>
    </div>
  );
}